package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.CompilerErrorCode;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Spy;
import org.mockito.junit.MockitoJUnitRunner;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class CheckGlobalThis_visit_TriageGen0Test {

    @Spy
    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Compiler compiler;

    @Mock
    private CompilerErrorCode error;

    @Before
    public void setUp() {
        // Accessing private/protected field via reflection or assuming availability in test context
        // Since we cannot change the source, we assume the class structure allows setting the compiler.
        // In a real scenario, one might use ReflectionTestUtils if using Spring, or direct field access if package-private.
        try {
            java.lang.reflect.Field compilerField = CheckGlobalThis.class.getDeclaredField("compiler");
            compilerField.setAccessible(true);
            compilerField.set(checkGlobalThis, compiler);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testVisit_NoThisNoAssignLhs() {
        when(n.getType()).thenReturn(Token.OTHER);
        // assignLhsChild is null by default or not set to n

        checkGlobalThis.visit(t, n, parent);

        verify(compiler, never()).report(any());
    }

    @Test
    public void testVisit_ThisButShouldNotReport() {
        when(n.getType()).thenReturn(Token.THIS);
        // Mocking the internal method shouldReportThis using a spy
        doReturn(false).when(checkGlobalThis).shouldReportThis(n, parent);

        checkGlobalThis.visit(t, n, parent);

        verify(compiler, never()).report(any());
    }

    @Test
    public void testVisit_ThisAndShouldReport() {
        when(n.getType()).thenReturn(Token.THIS);
        doReturn(true).when(checkGlobalThis).shouldReportThis(n, parent);
        when(t.makeError(n, any(), any())).thenReturn(error);

        checkGlobalThis.visit(t, n, parent);

        verify(compiler).report(error);
    }

    @Test
    public void testVisit_IsAssignLhsChild() throws Exception {
        // Set assignLhsChild via reflection to test the nullification branch
        java.lang.reflect.Field lhsField = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
        lhsField.setAccessible(true);
        lhsField.set(checkGlobalThis, n);

        when(n.getType()).thenReturn(Token.OTHER);

        checkGlobalThis.visit(t, n, parent);

        // Verify that assignLhsChild was set to null
        assert(lhsField.get(checkGlobalThis) == null);
    }

    @Test
    public void testVisit_ThisAndIsAssignLhsChild() throws Exception {
        // Test both IF branches being true
        java.lang.reflect.Field lhsField = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
        lhsField.setAccessible(true);
        lhsField.set(checkGlobalThis, n);

        when(n.getType()).thenReturn(Token.THIS);
        doReturn(true).when(checkGlobalThis).shouldReportThis(n, parent);
        when(t.makeError(n, any(), any())).thenReturn(error);

        checkGlobalThis.visit(t, n, parent);

        verify(compiler).report(error);
        assert(lhsField.get(checkGlobalThis) == null);
    }
}
